import {carById} from './racing-model.js';
const box=(c,x,y,w,h,r=8)=>{c.beginPath();c.roundRect(x,y,w,h,r);};
export function drawRaceCar(c,x,y,width,height,angle,config,{boost=false,rival=false,jump=0,police=false,brake=false,time=0}={}){
 c.save();c.translate(x+3+jump*.22,y+5+jump*.28);c.rotate(angle);c.fillStyle='#0006';box(c,-width/2,-height/2,width,height);c.fill();c.restore();
 c.save();c.translate(x,y-jump*.35);c.scale(1+jump*.0065,1+jump*.0065);c.rotate(angle);
 const type=config.bodyType||'sedan',w=width*(type==='suv'?1.12:type==='supercar'?1.08:1),h=height*(type==='suv'?1.04:1);
 if(boost){const len=h*(.44+Math.sin(time*37)*.1);for(const side of [-.26,.26]){const g=c.createLinearGradient(0,h/2,0,h/2+len);g.addColorStop(0,'#fff');g.addColorStop(.35,'#38bdf8');g.addColorStop(1,'#f43f5e00');c.fillStyle=g;c.beginPath();c.moveTo(w*side-4,h/2-2);c.lineTo(w*side+4,h/2-2);c.lineTo(w*side,h/2+len);c.fill();}}
 c.fillStyle='#070b12';for(const sx of [-1,1])for(const sy of [-1,1])c.fillRect(sx*w/2-2,sy*h*.27-h*.1,5,h*.2);
 const g=c.createLinearGradient(-w/2,0,w/2,0);g.addColorStop(0,config.accentColor||'#94a3b8');g.addColorStop(.18,config.bodyColor||'#64748b');g.addColorStop(.8,config.bodyColor||'#64748b');g.addColorStop(1,config.accentColor||'#94a3b8');c.fillStyle=g;c.beginPath();c.moveTo(-w*.29,-h*.5);c.quadraticCurveTo(0,-h*.56,w*.29,-h*.5);c.quadraticCurveTo(w*.47,-h*.47,w*.49,-h*.27);c.lineTo(w*.46,h*.24);c.quadraticCurveTo(w*.54,h*.39,w*.38,h*.49);c.quadraticCurveTo(0,h*.53,-w*.38,h*.49);c.quadraticCurveTo(-w*.54,h*.39,-w*.46,h*.24);c.lineTo(-w*.49,-h*.27);c.quadraticCurveTo(-w*.47,-h*.47,-w*.29,-h*.5);c.closePath();c.fill();c.strokeStyle=config.accentColor||'#e2e8f0';c.lineWidth=1.4;c.stroke();
 if(config.stripeColor){c.fillStyle=config.stripeColor;c.fillRect(-w*.12,-h/2+2,w*.24,h-4);}if(police){c.fillStyle='#f8fafc';c.fillRect(-w/2+2,-h*.18,w-4,h*.42);}
 for(const side of [-1,1]){c.fillStyle=config.bodyColor||'#64748b';box(c,side*w*.52-2,-h*.18,4,h*.085,2);c.fill();}c.strokeStyle='#f0f9ff55';c.lineWidth=.8;c.beginPath();for(const side of [-1,1]){c.moveTo(side*w*.31,-h*.43);c.lineTo(side*w*.25,-h*.27);c.moveTo(side*w*.39,-h*.1);c.lineTo(side*w*.37,h*.29);}c.stroke();
 c.fillStyle='#071522';box(c,-w*.38,-h*.23,w*.76,h*(type==='suv'?.66:.55),6);c.fill();c.fillStyle=police?'#f8fafc':config.bodyColor;box(c,-w*.28,-h*.06,w*.56,h*(type==='suv'?.38:.26),4);c.fill();
 c.strokeStyle='#c2edff66';c.lineWidth=1;c.beginPath();c.moveTo(-w*.3,-h*.18);c.lineTo(w*.3,-h*.18);c.stroke();
 if(type==='supercar'){c.fillStyle='#09090b';box(c,-w*.49,h/2-6,w*.98,5,2);c.fill();}
 if(police){const flash=Math.floor(time*9)%2;c.fillStyle=flash?'#ef4444':'#1e293b';c.fillRect(-w*.32,-2,w*.32,5);c.fillStyle=flash?'#1e293b':'#3b82f6';c.fillRect(0,-2,w*.32,5);}
 c.fillStyle=rival?'#fb7185':'#fff5b5';for(const sx of [-1,1])c.fillRect(sx*w*.32-3,-h/2+2,6,3);
 const family=carFaceFamily(config);if(config.id){c.strokeStyle='#d9e8ee99';c.lineWidth=1;const gy=-h/2+7;if(family==='bmw'){box(c,-w*.2,gy,w*.17,4,1);c.stroke();box(c,w*.03,gy,w*.17,4,1);c.stroke();}else if(family==='audi'){for(let i=0;i<4;i++){c.beginPath();c.arc((i-1.5)*2.4,gy,1.8,0,Math.PI*2);c.stroke();}}else{c.beginPath();c.arc(0,gy,3,0,Math.PI*2);c.stroke();}c.beginPath();c.moveTo(-w*.25,-h*.37);c.lineTo(-w*.19,-h*.28);c.moveTo(w*.25,-h*.37);c.lineTo(w*.19,-h*.28);c.stroke();}
 c.fillStyle=brake?'#ff2350':'#d83141';c.fillRect(-w/2+3,h/2-4,w-6,brake?4:2);c.restore();
}
export function drawRaceScene(c,race,time=0,input={},viewHeight=720,playerBottom=187){
 const d=race.diff,shift=viewHeight-533-playerBottom;c.save();c.translate(0,shift);c.fillStyle=d.scenery;c.fillRect(0,-shift,600,viewHeight);
 const curve=y=>race.curve(race.distance+(533-y)/1.45)-race.curve(race.distance),left=y=>80+curve(y),scroll=race.distance*1.45;
 for(let y=-shift;y<viewHeight-shift;y+=8){const x=left(y),stripe=Math.floor((y-scroll)/40)%2===0;c.fillStyle=d.road;c.fillRect(x,y,440,9);c.fillStyle=stripe?d.curb:'#e9ede9';c.fillRect(x-12,y,12,9);c.fillRect(x+440,y,12,9);if((((y-scroll)%80)+80)%80<42){c.fillStyle='#ffffff55';for(let i=1;i<4;i++)c.fillRect(x+110*i-2,y,4,9);}}
 for(let i=0;i<Math.ceil(viewHeight/100);i++){const y=-shift+((i*117+scroll*.55)%(viewHeight+250))-130;for(const x of [left(y)-40,left(y)+480]){c.fillStyle='#0002';c.beginPath();c.ellipse(x+3,y+5,17,24,0,0,Math.PI*2);c.fill();c.fillStyle='#72ad5766';c.beginPath();c.arc(x,y,16,0,Math.PI*2);c.fill();}}
 const remaining=race.length-race.distance;if(race.mode!=='drive'&&remaining<520){const y=533-remaining*1.45;for(let r=0;r<2;r++)for(let i=0;i<28;i++){c.fillStyle=(i+r)%2?'#0b1220':'#fff';c.fillRect(left(y)+i*16,y+r*16,16,16);}}
 for(const z of race.zones){const x=race.screenX(z.lane,z.y);c.save();c.translate(x,z.y);c.rotate(race.roadAngle(z.lane,z.y));c.globalAlpha=z.used?.35:1;const g=c.createLinearGradient(0,40,0,-40);g.addColorStop(0,'#0a7cbf');g.addColorStop(1,'#53dcff');c.fillStyle=g;box(c,-50,-40,100,80,9);c.fill();c.strokeStyle='#a6f3ff';c.lineWidth=2;c.stroke();c.strokeStyle='#fff6a3';c.lineWidth=7;c.lineJoin='round';for(const y of [-20,4,28]){c.beginPath();c.moveTo(-28,y);c.lineTo(0,y-13);c.lineTo(28,y);c.stroke();}c.restore();}
 for(const r of race.ramps){const x=race.screenX(r.lane,r.y),g=c.createLinearGradient(0,r.y+26,0,r.y-26);g.addColorStop(0,'#d97706');g.addColorStop(1,'#fde047');c.fillStyle=g;box(c,x-22,r.y-26,44,52,6);c.fill();c.fillStyle='#2a1b09';c.textAlign='center';c.font='bold 11px sans-serif';c.fillText('▲ JUMP',x,r.y+4);}
 for(const coin of race.coins){const x=race.screenX(coin.lane,coin.y);c.save();c.translate(x,coin.y);c.scale(Math.max(.3,Math.abs(Math.cos(time*6+coin.y*.02))),1);c.fillStyle='#facc15';c.strokeStyle='#fef08a';c.lineWidth=2;c.beginPath();c.arc(0,0,12,0,Math.PI*2);c.fill();c.stroke();c.fillStyle='#854d0e';c.font='bold 13px sans-serif';c.textAlign='center';c.fillText('₩',0,5);c.restore();}
 for(const t of race.traffic)drawRaceCar(c,race.screenX(t.lane,t.y),t.y,32,60,race.roadAngle(t.lane,t.y),{bodyColor:t.color,accentColor:'#cbd5e1'},{time});
 for(const r of race.rivals){const y=533-(r.distance-race.distance)*1.45;if(y< -shift-120||y>viewHeight-shift+120)continue;const x=race.screenX(r.lane,y),car=carById(r.id);drawRaceCar(c,x,y,34,64,race.roadAngle(r.lane,y),car,{boost:race.difficulty==='hell',rival:true,time});c.fillStyle='#0f172ae8';box(c,x-30,y-52,60,16,5);c.fill();c.fillStyle='#fda4af';c.font='bold 9px sans-serif';c.textAlign='center';c.fillText(car.shortBadge,x,y-40);}
 for(const p of race.police)drawRaceCar(c,race.screenX(p.lane,p.y),p.y,35,66,race.roadAngle(p.lane,p.y),{bodyType:'sedan',bodyColor:'#0f172a',accentColor:'#38bdf8'},{boost:true,rival:true,police:true,time});
 if(!race.invulnerable||Math.floor(race.invulnerable/4)%2===0)drawRaceCar(c,300+race.x*220,533,36,68,race.roadAngle(race.x,533)+race.tilt,race.car,{jump:race.jump,boost:race.boosting,brake:input.brake,time});
 if(race.boosting){c.strokeStyle='#bfedff55';c.lineWidth=2;for(let i=0;i<7;i++){const x=(i*97+time*13)%600,y=-shift+(i*233+time*1100)%viewHeight;c.beginPath();c.moveTo(x,y);c.lineTo(x,y+48);c.stroke();}}
 c.restore();
}

export function carFaceFamily(car){return ['3_series','5_series','x5','x6m','xm','m8'].includes(car.id)?'bmw':['a5','a6','a7','q8','rs6','rs7','r8'].includes(car.id)?'audi':'mercedes';}
/** Model-specific front portraits: kidney grilles, Audi hexagons and split LEDs. */
export function drawFrontCar(c,car){
 const family=carFaceFamily(car),suv=car.bodyType==='suv',sport=car.bodyType==='supercar',xm=car.id==='xm',w=car.id==='a7'?360:car.id==='a5'?335:suv?355:345,roof=car.id==='rs6'?-157:car.id==='a7'?-162:suv?-180:sport?-127:-150;
 c.save();c.translate(500,295);c.scale(sport?1.08:1.03,car.id==='rs6'?.84:sport?.77:suv?.9:.84);
 const shadow=c.createRadialGradient(0,160,20,0,160,430);shadow.addColorStop(0,'#000c');shadow.addColorStop(1,'#0000');c.fillStyle=shadow;c.beginPath();c.ellipse(0,160,430,48,0,0,Math.PI*2);c.fill();
 for(const side of [-1,1]){c.fillStyle='#06090f';box(c,side*(w-32)-29,30,58,155,19);c.fill();c.strokeStyle='#28323c';c.lineWidth=3;for(let x=-18;x<=18;x+=9){c.beginPath();c.moveTo(side*(w-32)+x,68);c.lineTo(side*(w-32)+x,168);c.stroke();}}
 c.beginPath();c.moveTo(-w,139);c.lineTo(-w+8,-11);c.quadraticCurveTo(-w+12,-48,-219,-66);c.lineTo(-177,roof);c.quadraticCurveTo(0,roof-36,177,roof);c.lineTo(219,-66);c.quadraticCurveTo(w-12,-48,w-8,-11);c.lineTo(w,139);c.quadraticCurveTo(0,176,-w,139);c.closePath();c.fillStyle=car.bodyColor;c.fill();
 const sheen=c.createLinearGradient(0,roof-20,0,170);sheen.addColorStop(0,'#ffffff66');sheen.addColorStop(.28,'#ffffff12');sheen.addColorStop(.47,'#ffffff55');sheen.addColorStop(.52,'#00000024');sheen.addColorStop(.75,'#ffffff14');sheen.addColorStop(1,'#00000088');c.fillStyle=sheen;c.fill();c.strokeStyle='#f3faff55';c.lineWidth=2;c.stroke();
 const glass=c.createLinearGradient(0,roof,0,-65);glass.addColorStop(0,'#050d18');glass.addColorStop(.55,'#213544');glass.addColorStop(1,'#0b1721');c.fillStyle=glass;c.beginPath();c.moveTo(-196,-65);c.lineTo(-156,roof+15);c.quadraticCurveTo(0,roof-6,156,roof+15);c.lineTo(196,-65);c.closePath();c.fill();c.strokeStyle='#c8dbea66';c.lineWidth=3;c.stroke();c.strokeStyle='#bad2e51c';c.lineWidth=12;c.beginPath();c.moveTo(-140,roof+29);c.lineTo(135,-84);c.stroke();
 for(const side of [-1,1]){c.fillStyle=car.bodyColor;box(c,side*252-29,-79,58,27,11);c.fill();c.strokeStyle='#e3f5ff88';c.lineWidth=2;c.stroke();c.strokeStyle='#eff8ff55';c.lineWidth=3;c.beginPath();c.moveTo(side*158,-51);c.quadraticCurveTo(side*183,-28,side*198,-7);c.stroke();}
 // Lower intakes, honeycomb mesh and sculpted bumper edges.
 c.fillStyle='#09131e';for(const [x,y,vw,vh]of [[-w+29,67,120,60],[-110,99,220,35],[w-149,67,120,60]]){box(c,x,y,vw,vh,7);c.fill();}c.save();c.beginPath();c.rect(-w+29,67,120,60);c.rect(w-149,67,120,60);c.clip();c.strokeStyle='#415364';c.lineWidth=2;for(let y=78;y<132;y+=12)for(let x=-w+30;x<w-29;x+=18){c.beginPath();c.moveTo(x,y);c.lineTo(x+7,y-4);c.lineTo(x+14,y);c.lineTo(x+7,y+4);c.closePath();c.stroke();}c.restore();
 const grille=(x,y,gw,gh,kidney=false)=>{c.beginPath();if(kidney){c.moveTo(x+15,y);c.lineTo(x+gw-13,y);c.quadraticCurveTo(x+gw+5,y+gh*.35,x+gw-8,y+gh-9);c.quadraticCurveTo(x+gw*.45,y+gh+5,x+8,y+gh-8);c.quadraticCurveTo(x-6,y+gh*.4,x+15,y);}else{c.moveTo(x+28,y);c.lineTo(x+gw-28,y);c.lineTo(x+gw,y+gh*.22);c.lineTo(x+gw-19,y+gh);c.lineTo(x+19,y+gh);c.lineTo(x,y+gh*.22);c.closePath();}c.fillStyle='#050b12';c.fill();c.strokeStyle=car.id==='xm'?'#a1afba':'#9eabb5';c.lineWidth=5;c.stroke();c.save();c.clip();c.strokeStyle='#526171';c.lineWidth=4;for(let line=y+12;line<y+gh;line+=13){c.beginPath();c.moveTo(x+5,line);c.lineTo(x+gw-5,line);c.stroke();}c.restore();};
 if(family==='bmw'){const large=suv,gw=large?109:83,gh=large?97:57,y=large?-2:12;grille(-gw-9,y,gw,gh,true);grille(9,y,gw,gh,true);c.fillStyle='#d7e5ed';c.beginPath();c.arc(0,y-15,10,0,Math.PI*2);c.fill();for(let i=0;i<4;i++){c.fillStyle=i%2?'#1f78ac':'#f0f5fa';c.beginPath();c.moveTo(0,y-15);c.arc(0,y-15,7,i*Math.PI/2,(i+1)*Math.PI/2);c.closePath();c.fill();}}
 else if(family==='audi'){grille(car.id==='r8'?-172:car.id==='a5'?-142:-158,car.id==='r8'?18:4,car.id==='r8'?344:car.id==='a5'?284:316,suv?113:car.id==='r8'?83:car.id==='a5'?90:102);c.strokeStyle='#dbe5ed';c.lineWidth=3;for(let i=0;i<4;i++){c.beginPath();c.ellipse(-33+i*22,25,16,10,0,0,Math.PI*2);c.stroke();}}
 else {grille(-139,13,278,84);c.strokeStyle='#c9d8e3';c.lineWidth=4;c.beginPath();c.arc(0,53,23,0,Math.PI*2);c.stroke();for(let i=0;i<3;i++){const a=-Math.PI/2+i*Math.PI*2/3;c.beginPath();c.moveTo(0,53);c.lineTo(Math.cos(a)*22,53+Math.sin(a)*22);c.stroke();}}
 // Light signatures follow the five reference vehicles rather than a shared bar.
 for(const side of [-1,1]){c.save();c.translate(side*(w-105),xm?-12:20);c.scale(side,1);c.fillStyle='#07111b';c.beginPath();c.moveTo(-74,-7);c.lineTo(74,-24);c.lineTo(60,1);c.lineTo(-64,14);c.closePath();c.fill();c.strokeStyle='#dcefff';c.shadowColor='#95ddff';c.shadowBlur=12;c.lineWidth=xm?4:6;c.beginPath();if(xm){c.moveTo(-61,-4);c.lineTo(64,-17);}else if(family==='bmw'){for(const x of [-34,15]){c.moveTo(x-17,1);c.lineTo(x+9,-7);c.lineTo(x-2,7);}}else if(family==='audi'){c.moveTo(-58,8);c.lineTo(47,-3);c.lineTo(63,-18);if(car.id==='r8'){c.moveTo(-53,-2);c.lineTo(40,-12);c.lineTo(31,0);}else for(let i=0;i<4;i++){c.moveTo(-40+i*24,-3-i*2);c.lineTo(-34+i*24,6-i*2);}}else{c.moveTo(-55,5);c.lineTo(44,-7);c.lineTo(61,-16);}c.stroke();c.shadowBlur=0;if(xm){c.fillStyle='#253746';box(c,-46,30,105,31,5);c.fill();c.fillStyle='#9db4c7';box(c,-33,38,32,9,3);c.fill();box(c,10,38,32,9,3);c.fill();}c.restore();}
 c.fillStyle='#d4dce0';box(c,-79,112,158,27,4);c.fill();c.fillStyle='#135282';c.fillRect(-78,115,12,21);c.fillStyle='#18222c';c.textAlign='center';c.font='bold 15px sans-serif';c.fillText(car.shortBadge.toUpperCase(),5,132);c.strokeStyle='#d9e9f044';c.lineWidth=3;c.beginPath();c.moveTo(-w+20,145);c.quadraticCurveTo(0,174,w-20,145);c.stroke();c.restore();
}
